import { useState, useEffect, useSyncExternalStore } from 'react'

function subscribeNoPw(cb) { window.addEventListener('uc_hide_nopw', cb); return () => window.removeEventListener('uc_hide_nopw', cb) }
function getNoPwHidden() { return !!localStorage.getItem('uc_hide_nopw') }
import { useWriteContract, useAccount, useWaitForTransactionReceipt, useReadContract } from 'wagmi'
import { useGuestChain } from './useGuestChain.js'
import { SAFE_ABI } from './abi.js'
import { getSafeAddress } from './config.js'
import { getTxUrl, fmtErr } from './chainUtils.js'
import { guardianSalt, deriveAccount, signSetGuardian, signRemoveGuardian, validatePassword } from './safeUtils.js'

const ETH = '0x0000000000000000000000000000000000000000'

export default function SafePasswordManager() {
  const noPwHidden = useSyncExternalStore(subscribeNoPw, getNoPwHidden)
  const { address } = useAccount()
  const { activeChainId: chainId } = useGuestChain()
  const SAFE_ADDRESS = getSafeAddress(chainId)


  const [oldPw, setOldPw] = useState('')
  const [newPw, setNewPw] = useState('')
  const [newPw2, setNewPw2] = useState('')
  const [txHash, setTxHash] = useState(null)
  const [status, setStatus] = useState('')
  const { writeContractAsync, isPending } = useWriteContract()
  const { isLoading: isConfirming, isSuccess } = useWaitForTransactionReceipt({ hash: txHash })

  const { data: guardian, refetch: refetchGuardian } = useReadContract({
    address: SAFE_ADDRESS, abi: SAFE_ABI, functionName: 'guardians',
    args: [address ?? ETH],
    chainId,
    query: { enabled: !!address },
  })
  const { data: nonce } = useReadContract({
    address: SAFE_ADDRESS, abi: SAFE_ABI, functionName: 'nonces',
    args: [address ?? ETH],
    chainId,
    query: { enabled: !!address },
  })

  const hasGuardian = guardian && guardian !== ETH
  const salt = address ? guardianSalt(chainId, address) : ''
  const newPwErr = validatePassword(newPw)
  const newPw2Err = newPw2 && newPw2 !== newPw ? 'Passwords do not match' : ''
  const oldPwErr = hasGuardian ? validatePassword(oldPw) : ''

  async function handleSet() {
    if (!address || newPwErr || newPw2Err || !newPw2) return
    try {
      setStatus('info:Deriving key…')
      const newAccount = await deriveAccount(newPw, salt)
      const newGuardian = newAccount.address
      let oldSig = '0x'
      if (hasGuardian) {
        if (oldPwErr) { setStatus('err:' + oldPwErr); return }
        const oldAccount = await deriveAccount(oldPw, salt)
        if (oldAccount.address.toLowerCase() !== guardian.toLowerCase()) {
          setStatus('err:Wrong current password'); return
        }
        oldSig = await signSetGuardian(oldPw, salt, {
          chainId, contractAddress: SAFE_ADDRESS,
          user: address, newGuardian, nonce: Number(nonce ?? 0),
        })
      }
      setStatus('info:Confirm in wallet…')
      const hash = await writeContractAsync({
        address: SAFE_ADDRESS, abi: SAFE_ABI, functionName: 'setGuardian',
        args: [newGuardian, oldSig],
      })
      setTxHash(hash)
      setStatus('info:Confirming…')
    } catch (e) {
      setStatus('err:' + fmtErr(e))
    }
  }

  async function handleRemove() {
    if (!address || !hasGuardian) return
    if (oldPwErr) { setStatus('err:' + oldPwErr); return }
    try {
      setStatus('info:Deriving key…')
      const oldAccount = await deriveAccount(oldPw, salt)
      if (oldAccount.address.toLowerCase() !== guardian.toLowerCase()) {
        setStatus('err:Wrong password'); return
      }
      const sig = await signRemoveGuardian(oldPw, salt, {
        chainId, contractAddress: SAFE_ADDRESS,
        user: address, nonce: Number(nonce ?? 0),
      })
      setStatus('info:Confirm in wallet…')
      const hash = await writeContractAsync({
        address: SAFE_ADDRESS, abi: SAFE_ABI, functionName: 'removeGuardian',
        args: [sig],
      })
      setTxHash(hash)
      setStatus('info:Confirming…')
    } catch (e) {
      setStatus('err:' + fmtErr(e))
    }
  }

  useEffect(() => {
    setOldPw(''); setNewPw(''); setNewPw2(''); setStatus(''); setTxHash(null)
  }, [chainId]) // eslint-disable-line
  useEffect(() => {
    if (isSuccess) { refetchGuardian(); setStatus('ok:✅ Done') }
  }, [isSuccess]) // eslint-disable-line

  const txUrl = txHash ? getTxUrl(chainId, txHash) : null
  const [dtype, dmsg] = status.includes(':') ? status.split(/:(.+)/) : ['info', status]

  const canSet = !newPwErr && !newPw2Err && newPw2 && (hasGuardian ? !oldPwErr : true)

  return (
    <div className="card">
      <h2>Vault Password</h2>
      <p className="sub">
        {hasGuardian
          ? '🔐 Password is set. Withdraw and transfers require it.'
          : '⚠️ No password set — vault is unprotected.'}
      </p>

      {hasGuardian && (
        <input className={`input ${oldPw && oldPwErr ? 'input-err' : oldPw && !oldPwErr ? 'input-ok' : ''}`}
          type="password" placeholder="Current password"
          value={oldPw} onChange={e => setOldPw(e.target.value)} />
      )}

      <input className={`input ${newPw && newPwErr ? 'input-err' : newPw && !newPwErr ? 'input-ok' : ''}`}
        type="password" placeholder={hasGuardian ? 'New password (min 6 chars)' : 'Password (min 6 chars)'}
        value={newPw} onChange={e => setNewPw(e.target.value)} />
      {newPw && newPwErr && <div className="status err" style={{marginTop:'4px'}}>{newPwErr}</div>}

      <input className={`input ${newPw2 && newPw2Err ? 'input-err' : newPw2 && !newPw2Err ? 'input-ok' : ''}`}
        type="password" placeholder={hasGuardian ? 'Confirm new password' : 'Confirm password'}
        value={newPw2} onChange={e => setNewPw2(e.target.value)} />
      {newPw2 && newPw2Err && <div className="status err" style={{marginTop:'4px'}}>{newPw2Err}</div>}

      <div style={{display:'flex', gap:'8px'}}>
        <button className="btn-primary" style={{flex:1}} onClick={handleSet}
          disabled={!canSet || isPending || isConfirming}>
          {isPending || isConfirming
            ? <><span className="spinner" /> {isConfirming ? 'Confirming…' : 'Confirm…'}</>
            : hasGuardian ? 'Change Password' : 'Set Password'}
        </button>
        {hasGuardian && (
          <button className="btn-danger" onClick={handleRemove}
            disabled={!!oldPwErr || isPending || isConfirming}>
            Remove Password
          </button>
        )}
      </div>

      {status && (
        <div className={`status ${dtype}`}>
          {dmsg}
          {txUrl && (isSuccess || isConfirming) && <> · <a href={txUrl} target="_blank" rel="noreferrer">View ↗</a></>}
        </div>
      )}
    </div>
  )
}
